package ai.interviewiq.api.service;
import ai.interviewiq.api.dto.AuthDtos.*; import ai.interviewiq.api.entity.User; import ai.interviewiq.api.exception.ApiException; import ai.interviewiq.api.repository.UserRepository; import ai.interviewiq.api.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.Locale;
@Service public class AuthService { final UserRepository users; final PasswordEncoder encoder; final JwtService jwt; public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} @Transactional public AuthResponse register(RegisterRequest r){String email=r.email().trim().toLowerCase(Locale.ROOT);if(users.existsByEmailIgnoreCase(email))throw new ApiException(HttpStatus.CONFLICT,"CONFLICT","An account already exists for this email.");User u=users.save(new User(email,encoder.encode(r.password()),r.displayName().trim()));return auth(u);} @Transactional public AuthResponse login(LoginRequest r){User u=users.findByEmailIgnoreCase(r.email().trim()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"UNAUTHENTICATED","Invalid email or password."));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"UNAUTHENTICATED","Invalid email or password.");u.setLastLoginAt(Instant.now());return auth(u);} public UserResponse me(Long id){return response(users.findById(id).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"UNAUTHENTICATED","Authentication is required.")));} @Transactional public UserResponse update(Long id,String name){User u=users.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","User not found."));u.setDisplayName(name.trim());return response(u);} private AuthResponse auth(User u){return new AuthResponse(response(u),jwt.create(u.getId(),u.getEmail()),jwt.expiry());} public static UserResponse response(User u){return new UserResponse(u.getId(),u.getEmail(),u.getDisplayName(),u.getStatus(),u.getCreatedAt(),u.getUpdatedAt());} }
